"""
Builds the BRSR report as a PDF using the Lucas TVS page template
(BRSR_Report_format.pptx).

--------------------------------------------------------------------------
PAGE TEMPLATE (taken from BRSR_Report_format.pptx)
--------------------------------------------------------------------------
- A4 portrait.
- Slide 1 (cover): full-height green side strip on the left (the repeating
  "Lucas TVS / ESG" strip image) + the Lucas TVS logo centred at the top.
- Slide 2 (every later page): the same green side strip only.
- Position/size of both images are stored as FRACTIONS of the page, copied
  from the PPTX (EMU / slide size), so they land in the same place on A4.
- Both images are embedded below as base64 (_LOGO_PNG_B64 / _SIDEBAR_PNG_B64)
  so no extra static files need to be deployed.
- All content is laid out to the right of the strip: see LEFT_MARGIN.

--------------------------------------------------------------------------
COLOURS
--------------------------------------------------------------------------
The template's strip is Lucas green (#196B24), so the header / label cells
that used to be navy now use that green (BRAND). Gold grid borders are kept.
To go back to navy, change only BRAND below.

--------------------------------------------------------------------------
Content logic (unchanged)
--------------------------------------------------------------------------
- _flatten_rows walks every sub_question in order: matrix grid / table grid /
  plain Q&A row. Nothing is dropped.
- Question rows are three columns (Number | Question | Answer).
- P1-P9 matrices and all table-shaped answers render as real grids.
- Combined ("All Plants") answers go through
  format_combined_answer_for_display() before being stringified;
  generate_brsr_pdf() accepts a precomputed `report_sections`.
--------------------------------------------------------------------------
"""

import base64
from io import BytesIO

from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER, TA_LEFT, TA_RIGHT, TA_JUSTIFY
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.utils import ImageReader, simpleSplit
from reportlab.pdfbase.pdfmetrics import stringWidth
from reportlab.platypus import (
    PageBreak,
    Paragraph,
    SimpleDocTemplate,
    Spacer,
    Table,
    TableStyle,
)

from .brsr_report_data import format_combined_answer_for_display

# ---------------------------------------------------------------------------
# Template images (from BRSR_Report_format.pptx), embedded as base64
# ---------------------------------------------------------------------------
_LOGO_PNG_B64 = ""
_SIDEBAR_PNG_B64 = ""

# Placement as fractions of the page (EMU / slide size in the PPTX).
# Slide size in the PPTX: 6858000 x 9906000 EMU.
_SIDEBAR_X_FRAC = 177828 / 6858000
_SIDEBAR_W_FRAC = 255560 / 6858000
_LOGO_X_FRAC = 2657841 / 6858000
_LOGO_Y_FRAC = 54598 / 9906000      # measured from the TOP of the slide
_LOGO_W_FRAC = 1359169 / 6858000
_LOGO_H_FRAC = 369821 / 9906000

_image_cache = {}


def _image(key, b64):
    if key not in _image_cache:
        _image_cache[key] = ImageReader(BytesIO(base64.b64decode(b64)))
    return _image_cache[key]


# ---------------------------------------------------------------------------
# Palette
# ---------------------------------------------------------------------------
BRAND = colors.HexColor("#196B24")        # Lucas green (side strip colour)
BRAND_TEXT = colors.white
GOLD_BORDER = colors.HexColor("#F4B000")
LINK_ORANGE = colors.HexColor("#C0504D")
BODY_TEXT = colors.HexColor("#1A1A1A")
MUTED_TEXT = colors.HexColor("#6B7280")
SECTION_LABEL_ORANGE = colors.HexColor("#F4A300")
PAGE_WHITE = colors.white

# Backwards-compatible names used elsewhere in the module
NAVY = BRAND
NAVY_TEXT = BRAND_TEXT
LUCAS_GREEN = BRAND
LUCAS_BLUE = BRAND
LUCAS_TABLE_BORDER = GOLD_BORDER
LUCAS_DARK = BODY_TEXT
LUCAS_MUTED = MUTED_TEXT
LUCAS_WHITE = PAGE_WHITE
LUCAS_BLACK = colors.black

# ---------------------------------------------------------------------------
# Page geometry -- content sits to the right of the green strip
# ---------------------------------------------------------------------------
PAGE_W, PAGE_H = A4
SIDEBAR_RIGHT = (_SIDEBAR_X_FRAC + _SIDEBAR_W_FRAC) * PAGE_W   # ~37.6pt
LEFT_MARGIN = 58
RIGHT_MARGIN = 38
TOP_MARGIN = 54
BOTTOM_MARGIN = 54
CONTENT_WIDTH = PAGE_W - LEFT_MARGIN - RIGHT_MARGIN            # ~499pt
TABLE_WIDTH = 480                                              # tables stay <= content width


def _display_financial_year(financial_year):
    if not financial_year:
        return "FY 2024-25"
    value = str(financial_year).strip()
    if value.upper().startswith("FY "):
        value = value[3:].strip()
    parts = value.split("-")
    if len(parts) == 2 and len(parts[0]) == 4 and len(parts[1]) == 4:
        value = f"{parts[0]}-{parts[1][-2:]}"
    return f"FY {value}"


def _short_company_name(company_name):
    value = (company_name or "Lucas TVS").strip()
    for suffix in (" Private Limited", " Limited", " Pvt. Ltd.", " Pvt Ltd", " Ltd.", " Ltd"):
        if value.lower().endswith(suffix.lower()):
            return value[: -len(suffix)].strip()
    return value


# ---------------------------------------------------------------------------
# Page templates (onFirstPage / onLaterPages)
# ---------------------------------------------------------------------------

def _draw_sidebar(canvas):
    """Full-height green Lucas TVS / ESG strip on the left (every page)."""
    canvas.drawImage(
        _image("sidebar", _SIDEBAR_PNG_B64),
        _SIDEBAR_X_FRAC * PAGE_W,
        0,
        width=_SIDEBAR_W_FRAC * PAGE_W,
        height=PAGE_H,
        mask="auto",
    )


def _draw_logo(canvas):
    """Lucas TVS logo, top centre (cover only)."""
    h = _LOGO_H_FRAC * PAGE_H
    canvas.drawImage(
        _image("logo", _LOGO_PNG_B64),
        _LOGO_X_FRAC * PAGE_W,
        PAGE_H - _LOGO_Y_FRAC * PAGE_H - h,
        width=_LOGO_W_FRAC * PAGE_W,
        height=h,
        mask="auto",
    )


def _draw_later_page(canvas, doc, financial_year, plant_name=None):
    canvas.saveState()
    _draw_sidebar(canvas)
    canvas.setFont("Helvetica-Bold", 10)
    canvas.setFillColor(BRAND)
    header = f"BRSR {_display_financial_year(financial_year)}"
    if plant_name:
        header = f"{str(plant_name)[:40]}  |  {header}"
    canvas.drawRightString(PAGE_W - RIGHT_MARGIN, PAGE_H - 34, header)
    canvas.setStrokeColor(GOLD_BORDER)
    canvas.setLineWidth(0.8)
    canvas.line(LEFT_MARGIN, PAGE_H - 40, PAGE_W - RIGHT_MARGIN, PAGE_H - 40)
    canvas.setFont("Helvetica", 9)
    canvas.setFillColor(MUTED_TEXT)
    canvas.drawRightString(PAGE_W - RIGHT_MARGIN, 30, str(canvas.getPageNumber()))
    canvas.restoreState()


def _fit_font_size(text, font_name, max_size, max_width, min_size=9):
    """Largest font size (<= max_size) at which `text` fits in max_width."""
    size = max_size
    while size > min_size and stringWidth(text, font_name, size) > max_width:
        size -= 0.5
    return size


def _draw_cover_page(canvas, doc, company_name, financial_year, company_cin, plant_name=None,
                     plants_included=None):
    """
    Cover layout (everything in the upper part of the page, under the logo):

        [logo]                           <- from the PPTX template
        ---------------- gold rule ----------------
              Business Responsibility
             & Sustainability Report
        ---------------- gold rule ----------------
                     FY 2026-27
        +----------------------------------------+
        |   COMPANY NAME   (green bar, white)    |
        +----------------------------------------+
        |   CIN: ...                             |
        |   Plant: ...                           |
        +----------------------------------------+
    """
    cx = LEFT_MARGIN + CONTENT_WIDTH / 2
    left = LEFT_MARGIN
    width = CONTENT_WIDTH

    canvas.saveState()
    _draw_sidebar(canvas)
    _draw_logo(canvas)

    # --- Title block ------------------------------------------------------
    rule1_y = PAGE_H - 125
    canvas.setFillColor(GOLD_BORDER)
    canvas.rect(left, rule1_y, width, 4, stroke=0, fill=1)

    canvas.setFillColor(BRAND)
    canvas.setFont("Times-Bold", 32)
    title_y = rule1_y - 52
    canvas.drawCentredString(cx, title_y, "Business Responsibility")
    canvas.drawCentredString(cx, title_y - 40, "& Sustainability Report")

    rule2_y = title_y - 40 - 26
    canvas.setFillColor(GOLD_BORDER)
    canvas.rect(left, rule2_y, width, 4, stroke=0, fill=1)

    # --- Financial year ---------------------------------------------------
    fy_y = rule2_y - 42
    canvas.setFillColor(BRAND)
    canvas.setFont("Times-Bold", 26)
    canvas.drawCentredString(cx, fy_y, _display_financial_year(financial_year))

    # --- Company details card --------------------------------------------
    bar_h = 38
    bar_top = fy_y - 36
    bar_y = bar_top - bar_h

    company_text = _short_company_name(company_name)
    canvas.setFillColor(BRAND)
    canvas.rect(left, bar_y, width, bar_h, stroke=0, fill=1)
    canvas.setFillColor(colors.white)
    size = _fit_font_size(company_text, "Times-Bold", 18, width - 24)
    canvas.setFont("Times-Bold", size)
    canvas.drawCentredString(cx, bar_y + (bar_h - size) / 2 + 2, company_text)

    lines = [(f"CIN: {company_cin}" if company_cin else "CIN: -", colors.black)]
    if plant_name:
        lines.append((f"Plant: {plant_name}", BRAND))

    # Consolidated report: list the plants it covers (wrapped, max 3 lines)
    covered_lines = []
    if plants_included:
        covered_text = f"Consolidated across {len(plants_included)} plant" \
                       f"{'s' if len(plants_included) != 1 else ''}: " + ", ".join(plants_included)
        covered_lines = simpleSplit(covered_text, "Times-Roman", 10.5, width - 28)
        if len(covered_lines) > 3:
            covered_lines = covered_lines[:3]
            covered_lines[-1] = covered_lines[-1].rstrip(" ,") + " ..."

    line_gap = 26
    covered_gap = 14
    box_h = 20 + line_gap * len(lines) + (10 + covered_gap * len(covered_lines) if covered_lines else 0)
    box_y = bar_y - box_h
    canvas.setFillColor(colors.white)
    canvas.setStrokeColor(GOLD_BORDER)
    canvas.setLineWidth(1.2)
    canvas.rect(left, box_y, width, box_h, stroke=1, fill=1)

    text_y = bar_y - 14 - 12
    for text, color in lines:
        canvas.setFillColor(color)
        size = _fit_font_size(text, "Times-Bold", 14, width - 24)
        canvas.setFont("Times-Bold", size)
        canvas.drawCentredString(cx, text_y, text)
        text_y -= line_gap

    if covered_lines:
        text_y += line_gap - 12          # step back up from the last gap
        canvas.setStrokeColor(colors.HexColor("#D1D5DB"))
        canvas.setLineWidth(0.6)
        canvas.line(left + 14, text_y + 4, left + width - 14, text_y + 4)
        text_y -= 10
        canvas.setFillColor(MUTED_TEXT)
        canvas.setFont("Times-Roman", 10.5)
        for line in covered_lines:
            canvas.drawCentredString(cx, text_y, line)
            text_y -= covered_gap

    canvas.restoreState()


